#include <stdio.h>
#include <stdlib.h>

void getResult(int n, int weights[]);

int main() {
    int n;
    scanf("%d", &n);

    int weights[n];
    for(int i=0; i<n; i++) {
        scanf("%d", &weights[i]);
    }

    getResult(n, weights);

    return 0;
}

int cmp(const void* a, const void* b) {
    return (*(int*) a) - (*(int*) b);
}

void getResult(int n, int weights[]) {
    qsort(weights, n, sizeof(int), cmp);

    int min = weights[0];

    int correctSum = min;
    int faultSum = min;

    for(int i=1; i<n; i++) {
        correctSum += weights[i];
        faultSum ^= weights[i];
    }

    if(faultSum == 0) {
        printf("%d\n", correctSum - min);
    } else {
        puts("NO");
    }
}
